    previewImage: r.preview_image,
    note: r.note,
    tags: JSON.parse(r.tags || '[]'),
    readLater: !!r.read_later,
    archived: !!r.archived,
    createdAt: r.created_at,
    seq: r.seq,
    fetchFailed: !!r.fetch_failed,
