async function saveToArchiveOrg(rawUrl) {
  const url = withScheme(rawUrl);
  const res = await fetch('https://web.archive.org/save/' + url, {
    method: 'GET',
    redirect: 'follow',
    headers: { 'User-Agent': UA, 'Accept': 'text/html,*/*' },
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
